<?php

declare(strict_types=1);

namespace Saij\WpAppFramework\Manifest;

use RuntimeException;
use Saij\WpAppFramework\Block\BlockDefinition;
use Saij\WpAppFramework\DependencyInjection\NoService;
use Saij\WpAppFramework\Hook\HookDefinition;
use Saij\WpAppFramework\Rest\RestRouteDefinition;
use Saij\WpAppFramework\Twig\TemplateRenderer;

/**
 * Loads a manifest file generated by the build: plain data, interpreted by the
 * container, the registrars and the value factory without reflection.
 *
 * The manifest format is internal and may change between framework versions;
 * a manifest with a different format version must be rebuilt.
 *
 * @internal
 *
 * @phpstan-import-type HookArgument from HookDefinition
 * @phpstan-import-type RestArgument from RestRouteDefinition
 * @phpstan-import-type RestPermission from RestRouteDefinition
 * @phpstan-import-type TemplateCallableEntry from TemplateRenderer
 * @phpstan-import-type BlockArgs from BlockDefinition
 * @phpstan-import-type BlockArgument from BlockDefinition
 * @phpstan-import-type BlockEditor from BlockDefinition
 * @phpstan-import-type BlockExcerpt from BlockDefinition
 * @phpstan-import-type BlockSupportEntry from BlockDefinition
 * @phpstan-import-type ValueField from \Saij\WpAppFramework\Value\ValueFactory
 * @phpstan-import-type PostClassEntry from \Saij\WpAppFramework\Post\PostTypeCollector
 * @phpstan-import-type TaxonomyEntry from \Saij\WpAppFramework\Post\PostTypeCollector
 * @phpstan-import-type MetaEntry from \Saij\WpAppFramework\Post\PostTypeCollector
 * @phpstan-import-type ServiceArgument from \Saij\WpAppFramework\DependencyInjection\Container
 * @phpstan-import-type SettingsGroupEntry from \Saij\WpAppFramework\Setting\SettingsCollector
 * @phpstan-import-type CacheEntry from \Saij\WpAppFramework\Cache\CachePolicy
 * @phpstan-type HookEntry array{name: string, priority: int, acceptedArgs: int, filter: bool, class: class-string, method: string, arguments: list<HookArgument>}
 * @phpstan-type RouteEntry array{
 *     namespace: non-falsy-string,
 *     route: non-falsy-string,
 *     methods: list<string>,
 *     args: array<string, array<string, mixed>>,
 *     permission: RestPermission,
 *     class: class-string,
 *     method: string,
 *     arguments: list<RestArgument>,
 *     void: bool,
 *     cache: CacheEntry|null
 * }
 * @phpstan-type BlockEntry array{
 *     name: string,
 *     args: BlockArgs,
 *     class: class-string,
 *     arguments: list<BlockArgument>,
 *     editor: BlockEditor,
 *     excerpt: BlockExcerpt,
 *     supports: list<BlockSupportEntry>,
 *     viewScript: string|null,
 *     cache: CacheEntry|null
 * }
 * @phpstan-type ManifestData array{
 *     format: int,
 *     kind: value-of<\Saij\WpAppFramework\Project\ProjectKind>,
 *     slug: non-empty-string|null,
 *     namespace: non-empty-string,
 *     parent: non-empty-string|null,
 *     candidates: list<class-string>,
 *     services: array<class-string, array<string, ServiceArgument>>,
 *     hooks: list<HookEntry>,
 *     routes: list<RouteEntry>,
 *     templateCallables: list<TemplateCallableEntry>,
 *     blocks: list<BlockEntry>,
 *     values: array<class-string, array<string, ValueField>>,
 *     publicApis: list<class-string>,
 *     templateProviders: array<non-empty-string, non-empty-string>,
 *     templateVersion: non-empty-string|null,
 *     codeVersion: non-empty-string|null,
 *     styles: bool,
 *     settings: array{title: string|null, groups: list<SettingsGroupEntry>},
 *     posts: array<class-string<\Saij\WpAppFramework\Post\AbstractPost>, PostClassEntry>,
 *     taxonomies: array<class-string, TaxonomyEntry>,
 *     meta: array<class-string, MetaEntry>,
 *     rewrite: non-empty-string|null
 * }
 */
#[NoService]
final class Manifest
{
    public const int FORMAT = 17;

    /**
     * @return ManifestData
     */
    public static function load(string $file): array
    {
        if (!is_file($file)) {
            throw new RuntimeException(sprintf('Manifest file %s does not exist.', $file));
        }

        $manifest = require $file;

        if (!is_array($manifest) || ($manifest['format'] ?? null) !== self::FORMAT) {
            throw new RuntimeException(sprintf(
                'Manifest file %s has an unsupported format (expected format %d). Rebuild the manifest with the installed framework version.',
                $file,
                self::FORMAT,
            ));
        }

        /** @var ManifestData $manifest Written by ManifestGenerator in this format version. */
        return $manifest;
    }
}
